#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")"
container_name="xdcnetwork-testnet-node"
image=$(docker inspect -f '{{.Config.Image}}' "$container_name")
datadir="$PWD/xdcchain-testnet"
head=$(docker exec "$container_name" XDC attach --exec 'eth.getBlock("latest").number' /work/xdcchain/XDC.ipc)
echo "current block: $head"
docker stop -t 120 "$container_name"
run() { local sub=$1; shift; docker run --rm --network none -v "${datadir}:/work/xdcchain" --entrypoint XDC "$image" db "$sub" --datadir /work/xdcchain "$@"; }
run put "0x5844506f532d56322d947b99b4933283f5e12805fea821114054d796ceada117cdbab73208bc891e66" ""
run put "0x5844506f532d56322d6759c616ed596754f8d26ac956dea415778b327b77fc9d69d07a747de2a74277" ""
while read -r number key; do
    [[ "$number" -le "$head" ]] && continue
    run delete "$key" || true
done <<'LIST'
